<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientTokenEndpointAuthMethodAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTokenEndpointAuthMethodAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientTokenEndpointAuthMethodAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTokenEndpointAuthMethod returns null on a freshly created holder.
     */
    public function testTokenEndpointAuthMethodNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTokenEndpointAuthMethodAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTokenEndpointAuthMethodAssigned());
        $this->assertNull($holder->getTokenEndpointAuthMethod());
    }
}
class ImplWithTrustedClientTokenEndpointAuthMethodAttributeHolderUnitTest
{
    use TrustedClientTokenEndpointAuthMethodAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTokenEndpointAuthMethodRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTokenEndpointAuthMethod();
    }
}
